#!/bin/bash
# rca-trace-axis-26-10-31 — the per-trace root-cause axis's probe runs (plans/rca-arms.md, addendum 2026-10-31;
# D-TBR-15), run by the EC2 replica infra/algos/seq2cause-bench-26-10-31-rca-trace-axis.tfvars as
# `bash scripts/jobs/rca-trace-axis-26-10-31.sh` from benchmarks/trace-bench-rca (the box's cwd). One command per
# line (scripts/tfvars_check.py follows the `bash …` segment and parses every tracebenchrca command with the
# real parsers); `set -e` stops at the first failure so a half-run never masquerades as a run.
# Per corpus xs → s → m, seeds 0–4: pull (tier rca, from the public dataset host) → export (asserted equal, case
# by case, to the landed export-trace record) → the tolerance re-probe of the landed case-level selection
# (`--axis ranking --select window --cap 500`, both arms, GPU; compared trace by trace with the landed CPU work
# files by `tolerance` after the sync) → the per-trace probe (`--axis trace --select post-nonok --cap 0`, both
# arms, GPU) → the raw shards deleted. Backbones are input artifacts (input/<rung>-s<k>/model, hash-checked
# against the committed freezes); the runner's environment is built by the replica's setup_command.
# Everything lands under out/ (synced to the run's prefix by the provisioning; the manifest is the last line).
set -euo pipefail
TP=$HOME/miniforge3/envs/seq2cause-trace-bench/bin/python
HR=../..
L=../trace-bench/plans/staging-ledger.json
python -m tracebenchrca.pull --repo chadyuk/trace-bench --revision v0.3.0 --rung xs --variant latent --seed 0 --tier rca --dest corpora --output-folder out/trace-axis/xs-s0/pull-rca
python -m tracebenchrca.export --corpus-dir corpora/instances/xs/latent/seed=0 --rung xs --out exports/xs-s0 --workers 4 --extras --expect-cases results/xs/latent/seed=0/export-trace/run/results.json --output-folder out/trace-axis/xs-s0/export
python -m tracebenchrca.ranktrace --axis ranking --select window --cap 500 --arm rca/trace --export-record out/trace-axis/xs-s0/export --corpus-dir corpora/instances/xs/latent/seed=0 --model-dir input/xs-s0/model --freeze ../trace-bench/freezes/2026-09-25-xs-latent-s0.json --rung xs --seed 0 --trace-python $TP --harness-root $HR --device cuda --work-dir out/trace-axis/work-window/xs-s0-rca-trace --prior-rung-record smallest-rung --staging-ledger $L --output-folder out/trace-axis/xs-s0/window/rca-trace/rank
python -m tracebenchrca.ranktrace --axis ranking --select window --cap 500 --arm rca/trace-core --export-record out/trace-axis/xs-s0/export --corpus-dir corpora/instances/xs/latent/seed=0 --model-dir input/xs-s0/model --freeze ../trace-bench/freezes/2026-09-25-xs-latent-s0.json --rung xs --seed 0 --trace-python $TP --harness-root $HR --device cuda --work-dir out/trace-axis/work-window/xs-s0-rca-trace-core --prior-rung-record smallest-rung --staging-ledger $L --output-folder out/trace-axis/xs-s0/window/rca-trace-core/rank
